const personalDimensions={enjoyment:'Enjoyment',connection:'Connection',security:'Security',meaning:'Meaning'};
const personalFields=['scaleDefinition','anchorLow','anchorMid','anchorHigh',...Object.keys(personalDimensions).map(k=>'weight_'+k)];
let personalRevision=null;
try{const profile=JSON.parse(localStorage.getItem('worth-personal-scale')||'null');if(profile&&typeof profile==='object'){personalFields.forEach(id=>{if(profile[id]!==undefined)$(id).value=profile[id]});personalRevision=profile.revision||null;put('personalStatus','Your saved scale is loaded. You can update it as your priorities change.')}}catch{}
function getPersonalProfile(){return Object.fromEntries(personalFields.map(id=>[id,$(id).value.trim()]))}
function validProfile(p){return Object.keys(personalDimensions).every(k=>{const v=p['weight_'+k];return v!==''&&Number.isInteger(Number(v))&&Number(v)>=0&&Number(v)<=5})}
function personalFit(prefix,p){const weights=Object.keys(personalDimensions).map(k=>Number(p['weight_'+k])),sum=weights.reduce((a,b)=>a+b,0);if(!validProfile(p)||sum===0)return null;let value=0;for(const [i,key] of Object.keys(personalDimensions).entries()){if(weights[i]===0)continue;const input=$(prefix+key);if(input.value==='')return null;const rating=Number(input.value);if(!Number.isFinite(rating)||rating<0||rating>10)return null;value+=rating*weights[i]}return value/sum}
function personalSummary(p){const total=Object.keys(personalDimensions).reduce((a,k)=>a+Number(p['weight_'+k]||0),0);return Object.entries(personalDimensions).map(([k,label])=>`${label} ${total?Math.round(Number(p['weight_'+k]||0)/total*100):0}%`).join(' · ')}
function augmentPersonal(){if(!current)return;const p=getPersonalProfile();const box=$('numberDashboard');const previous=box.querySelector('.personal-result');if(previous)previous.remove();const panel=document.createElement('section');panel.className='personal-result';box.prepend(panel);addText(panel,'p','Your personal reference points','eyebrow');addText(panel,'p',p.scaleDefinition||'Define what “happiness” means to you above. Your scores currently have no personal definition.','helper');const anchored=p.anchorLow&&p.anchorMid&&p.anchorHigh;addText(panel,'p',anchored?`0 = ${p.anchorLow} · 5 = ${p.anchorMid} · 10 = ${p.anchorHigh}`:'Add your 0, 5, and 10 examples to give the ratings a consistent meaning.','helper');addText(panel,'p','Compare these options using the same anchors. Scores from different people or different scale definitions are not directly comparable. An 8/10 is not “twice as happy” as 4/10.','helper');const doFit=personalFit('fitDo_',p),altFit=personalFit('fitAlt_',p);const fit=document.createElement('details');panel.append(fit);addText(fit,'summary','Personal priorities and fit');if(!validProfile(p))addText(fit,'p','Enter a whole-number importance from 0 to 5 for every dimension.');else{const total=Object.keys(personalDimensions).reduce((a,k)=>a+Number(p['weight_'+k]),0);if(total===0)addText(fit,'p','All dimensions have zero importance. No personal-fit score can be calculated.');else{addText(fit,'p',personalSummary(p),'helper');addText(fit,'p',`Personal fit · first option: ${doFit===null?'not enough ratings':doFit.toFixed(1)+'/10'} · alternative: ${altFit===null?'not enough ratings':altFit.toFixed(1)+'/10'}.`);addText(fit,'p','Fit = sum of (your dimension rating × your importance) ÷ total importance. Only dimensions with nonzero importance need ratings. Fit and expected happiness stay separate.','helper')}}
const snapshot={...p,revision:personalRevision,capturedAt:new Date().toISOString(),scoreDoNow:current.scoreDoNow,scoreAltNow:current.scoreAltNow,scoreDoLater:current.scoreDoLater,scoreAltLater:current.scoreAltLater,horizon:current.scoreHorizon,fitDo:doFit,fitAlt:altFit,ratings:Object.fromEntries(Object.keys(personalDimensions).map(k=>[k,{do:$('fitDo_'+k).value,alt:$('fitAlt_'+k).value}]))};current.personalScale=snapshot;current.profileSummary+='\n\nPERSONAL SCALE AT THE TIME\nDefinition: '+(p.scaleDefinition||'not defined')+'\n0: '+(p.anchorLow||'not defined')+'\n5: '+(p.anchorMid||'not defined')+'\n10: '+(p.anchorHigh||'not defined')+'\nPriorities: '+personalSummary(p)+'\nPersonal fit: first '+(doFit===null?'not rated':doFit.toFixed(1))+'; alternative '+(altFit===null?'not rated':altFit.toFixed(1));}
const originalNumbers=renderNumbers;renderNumbers=function(){originalNumbers();augmentPersonal()};$('form').addEventListener('submit',augmentPersonal);
function refreshPersonal(){if(current&&$('form').checkValidity()){addPerspective();renderNumbers()}}
personalFields.forEach(id=>$(id).addEventListener('input',()=>{put('personalStatus','Using these edits for this comparison. Save to keep them on this device.');refreshPersonal()}));Object.keys(personalDimensions).forEach(k=>['fitDo_','fitAlt_'].forEach(prefix=>$(prefix+k).addEventListener('input',refreshPersonal)));
$('savePersonal').onclick=()=>{const profile=getPersonalProfile();if(!validProfile(profile)){put('personalStatus','Use whole-number importance values from 0 to 5.');return}if(!profile.scaleDefinition||!profile.anchorLow||!profile.anchorMid||!profile.anchorHigh){put('personalStatus','Add your definition and all three anchors before saving your scale.');return}const revision=new Date().toISOString();try{localStorage.setItem('worth-personal-scale',JSON.stringify({...profile,revision}));personalRevision=revision;put('personalStatus','Personal scale saved on this device. Existing decisions keep their original definitions.');refreshPersonal()}catch{put('personalStatus','Storage is unavailable. Your scale still applies to this comparison but could not be saved.')}};
function decorateFollowups(){if(window.WamDecisionLearning)window.WamDecisionLearning.decorateFollowups();}
const originalReflectionRender=render;render=function(){originalReflectionRender();decorateFollowups()};decorateFollowups();
